            // seconds to kill monster
            long long seconds = (HPM + atk_eff - 1) / atk_eff;

            int def_eff = ATKM - DEFY - dd;
            if (def_eff < 0) def_eff = 0;

            long long total_damage = (long long)def_eff * seconds;

            // Need HPY + dh > total_damage
            // dh >= total_damage - HPY + 1, but at least 0
            long long dh = total_damage - HPY + 1;
            if (dh < 0) dh = 0;

            long long cost = (long long)da * a + (long long)dd * d + dh * h;
            if (cost < mini) mini = cost;
        }
    }

    printf("%lld\n", mini);

    return 0;
}

