#include<stdio.h>
#include<stdlib.h>
#include<string.h>

typedef struct node{ int v; struct node *next; } NODE;

int n, m;
int f[100001];
char v1[100001], v2[100001];
NODE *e[100001], *b[100001];
int stk[100001];

void dfs_forward(int start) {
    int top = 0;
    stk[top++] = start;
    v1[start] = 1;
    while (top > 0) {
        int cur = stk[--top];
        if (f[cur] == 1 && cur != start) continue; // don't expand through other assignments
        for (NODE *t = e[cur]; t; t = t->next) {
            if (!v1[t->v]) {
                v1[t->v] = 1;
                if (f[t->v] != 1) stk[top++] = t->v;
            }
        }
    }
}

void dfs_backward(int start) {
    int top = 0;
    stk[top++] = start;
    v2[start] = 1;
    while (top > 0) {
        int cur = stk[--top];
        if (f[cur] == 1) continue;
        for (NODE *t = b[cur]; t; t = t->next) {
            if (!v2[t->v]) { v2[t->v] = 1; stk[top++] = t->v; }
        }
    }
}

