import java.util.*

val scanner = Scanner(System.`in`)

fun readInt(): Int = scanner.nextInt()

fun readString(): String = scanner.next()

fun maximize(number: String, swaps: Int): String {
    val digits = StringBuilder(number)
    val length = digits.length
    var remainingSwaps = swaps

    for (i in 0 until length) {
        if (remainingSwaps == 0) break
        // Find the maximum digit in range [i, min(i + remainingSwaps, length - 1)]
        val end = minOf(i + remainingSwaps, length - 1)
        var maxPos = i
        for (j in i + 1..end) {
            if (digits[j] > digits[maxPos]) {
                maxPos = j
            }
        }
        // Bring digits[maxPos] to position i
        val ch = digits[maxPos]
        for (j in maxPos downTo i + 1) {
            digits[j] = digits[j - 1]
        }
        digits[i] = ch
        remainingSwaps -= (maxPos - i)
    }

    return digits.toString()
}

fun main() = maximize(readString(), readInt()).run(::println)

