fun main() {
    val (n, x, pos) = readLine()!!.trim().split(" ").map { it.toInt() }
    val MOD = 1_000_000_007L

    // Simulate binary search, count positions that must be < x and > x
    var less = 0  // positions that must have value < x
    var greater = 0  // positions that must have value > x

    var l = 0
    var r = n
    while (l < r) {
        val m = (l + r) / 2
        if (m == pos) break
        if (m < pos) {
            // need a[m] < x
            less++
            l = m + 1
        } else {
            // need a[m] > x
            greater++
            r = m
        }
    }

    // Available: (x-1) values less than x, (n-x) values greater than x
    if (less > x - 1 || greater > n - x) {
        println(0)
        return
    }

    // Count permutations
    // Choose `less` values from x-1 for the less positions: P(x-1, less)
    // Choose `greater` values from n-x for the greater positions: P(n-x, greater)
    // Remaining n-1-less-greater positions can be filled with remaining values: (n-1-less-greater)!

    var result = 1L
    // P(x-1, less) = (x-1)! / (x-1-less)!
    for (i in 0 until less) {
        result = result * ((x - 1 - i).toLong()) % MOD
    }
    // P(n-x, greater) = (n-x)! / (n-x-greater)!
    for (i in 0 until greater) {
        result = result * ((n - x - i).toLong()) % MOD
    }
    // (n-1-less-greater)!
    val remaining = n - 1 - less - greater
    for (i in 1..remaining) {
        result = result * i.toLong() % MOD
    }

    println(result)
}

