import math

def pipes(m, k):
    # Using top m splitters: k, k-1, ..., k-m+1
    # Total = 1 + sum_{i=k-m+1}^{k} (i-1) = 1 + sum_{j=k-m}^{k-1} j
    # = 1 + (k-m + k-1)*m/2
    return 1 + m * (2*k - m - 1) // 2

line = input().split()
n, k = int(line[0]), int(line[1])

if n == 1:
    print(0)
else:
    # Maximum splitters we can use is k-1 (splitters 2..k)
    max_m = k - 1
    max_pipes = 1 + max_m * (2*k - max_m - 1) // 2

    if max_pipes < n:
        print(-1)
    else:
        # Binary search for minimum m
        lo, hi = 1, max_m
        while lo < hi:
            mid = (lo + hi) // 2
            if pipes(mid, k) >= n:
                hi = mid
            else:
                lo = mid + 1
        print(lo)

