    n = len(s)

    # dp[i][has_at] = best string or None
    INF = None
    dp = [[None, None] for _ in range(n+1)]
    dp[0][0] = ""

    def better(a, b):
        # return True if a is better than b (shorter, then lex smaller)
        if a is None: return False
        if b is None: return True
        if len(a) != len(b): return len(a) < len(b)
        return a < b

    for i in range(n):
        for ha in range(2):
            if dp[i][ha] is None:
                continue
            cur = dp[i][ha]
            # Option 1: take s[i] as literal
            nxt = cur + s[i]
            if better(nxt, dp[i+1][ha]):
                dp[i+1][ha] = nxt
            # Option 2: replace 'dot' with '.'
            if i+3 <= n and s[i:i+3] == 'dot':
                # can replace if i > 0 and i+3 < n
