    best_price = p

    # Try each possible number of trailing nines k from 1 to 19
    for k in range(1, 20):
        power = 10 ** k
        suffix = power - 1  # k nines

        # largest number <= p ending in k nines
        remainder = p % power
        if remainder == suffix:
            candidate = p
        elif remainder < suffix:
            candidate = p - remainder - 1  # = (p // power - 1) * power + suffix
        else:
