- For position 1, we can place value 1 (fixed point) → f(n-1) involutions for rest
- Or place value j (j > 1) at position 1, which means position j gets value 1, and remaining n-2 positions form an involution → (n-1) choices, each giving f(n-2) involutions

Let me implement this greedy selection:

```csharp
using System;
using System.Collections.Generic;

namespace Rextester
{
    public class Program
    {
        static long[] inv = new long[55];

        static void Main(string[] args)
        {
            var arg = Console.ReadLine().Split(' ');
            int n = int.Parse(arg[0]);
            long k = long.Parse(arg[1]);

            long cap = (long)1e18;
            inv[0] = 1; inv[1] = 1;
            for (int i = 2; i <= 52; i++) {
                inv[i] = Math.Min(cap, inv[i-1] + Math.Min(cap, (long)(i-1) * inv[i-2]));
            }

            int[] perm = new int[n+1];
            bool[] used = new bool[n+1];

            // available positions/values, process greedily
            // We process available elements in order
            List<int> avail = new List<int>();
            for (int i = 1; i <= n; i++) avail.Add(i);

            while (avail.Count > 0) {
                int first = avail[0];
                avail.RemoveAt(0);
                int m = avail.Count;

                // Option 1: first is a fixed point, f(m) permutations
                long fixedCount = (m <= 52) ? inv[m] : cap;
                if (k <= fixedCount) {
                    perm[first] = first;
                    // continue with remaining
                } else {
                    k -= fixedCount;
                    // Option 2: first pairs with avail[j], each giving inv[m-1] options
                    long pairCount = (m-1 <= 52) ? inv[m-1] : cap;
                    // find which j
                    int jIdx = (int)((k - 1) / pairCount);
                    k = k - (long)jIdx * pairCount;
                    int partner = avail[jIdx];
                    avail.RemoveAt(jIdx);
                    perm[first] = partner;
                    perm[partner] = first;
                }
            }

            var result = new List<string>();
            for (int i = 1; i <= n; i++) result.Add(perm[i].ToString());
            Console.WriteLine(String.Join(" ", result));
        }
    }
}
