public class Solver
{
    public void Solve()
    {
        int k = ReadInt();
        var cnt = new int[256];
        foreach (char ch in string.Concat(ReadLines(4)))
            if (ch >= '1' && ch <= '9')
                cnt[ch]++;
        bool ok = true;
        for (char c = '1'; c <= '9'; c++)
            if (cnt[c] > 2 * k)
                ok = false;
        Write(ok ? "YES" : "NO");
    }

    #region Main

    protected static TextReader reader;
    protected static TextWriter writer;

