            int i = lo - 1, j = hi + 1;
            while (true)
            {
                do { i++; } while (a[i].CompareTo(pivot) < 0);
                do { j--; } while (a[j].CompareTo(pivot) > 0);
                if (i >= j)
                    return j;
                var temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }
        }
