        // State: (coverage mask of current row, dominator mask of current row)
        // coverage mask: which cells in current row are covered
        // dominator mask: which cells in current row are dominators (needed to cover next row)

        int fullMask = (1 << C) - 1;

        // Precompute for each possible dominator row mask S:
        // - cells in same row covered by S: S | expand(S)
        // expand(S) = left and right neighbors
        // - coverage provided to adjacent rows: S itself

        int[] expand = new int[1 << C];
        for (int s = 0; s < (1 << C); s++)
        {
            int e = s;
            for (int c = 0; c < C; c++)
            {
                if ((s >> c & 1) == 1)
                {
                    if (c > 0) e |= 1 << (c - 1);
                    if (c < C - 1) e |= 1 << (c + 1);
                }
            }
            expand[s] = e;
        }

