        // covCur: coverage of current row (must be full before moving to next)
        // domCur: dominator mask of current row (provides coverage to next row)

        // Actually let's redefine:
        // After processing row i, state = (dominator mask of row i, which cells of row i are covered)
        // Before moving to row i+1, row i must be fully covered.
        // But row i can be covered by: its own dominators (expand), dominators from row i-1 (from above), dominators from row i+1 (from below, next step)
        // This makes it tricky.

        // Standard approach:
        // State after choosing dominators for row i:
        //   prev_dom: dominator mask of row i (affects row i+1)
        //   cur_cov: coverage of row i so far (from row i's own expand + prev row's dom)
        // When we process row i+1 with dom mask S:
        //   row i gets additional coverage from S (cells in row i directly above cells in S)
        //   row i must then be fully covered
        //   row i+1's coverage = expand[S] | prev_dom (prev_dom covers cells directly below it)

        // dp[prev_dom][cur_cov] = min dominators
        // Initialize for row 0 (no previous row)
        // For each choice S for row 0:
        //   coverage of row 0 from itself = expand[S]
        //   no previous row, so cur_cov = expand[S]
        //   dp[S][expand[S]] = popcount(S)

        int states = 1 << C;
        int[,] dp = new int[states, states];
        for (int i = 0; i < states; i++)
            for (int j = 0; j < states; j++)
                dp[i, j] = INF;

        for (int s = 0; s < states; s++)
        {
            int cov = expand[s];
            int cnt = popcount(s);
            if (dp[s, cov] > cnt)
                dp[s, cov] = cnt;
        }

        for (int row = 1; row < R; row++)
        {
            int[,] ndp = new int[states, states];
            for (int i = 0; i < states; i++)
                for (int j = 0; j < states; j++)
                    ndp[i, j] = INF;

            for (int prevDom = 0; prevDom < states; prevDom++)
            {
                for (int prevCov = 0; prevCov < states; prevCov++)
                {
                    if (dp[prevDom, prevCov] == INF) continue;
                    int val = dp[prevDom, prevCov];

                    for (int s = 0; s < states; s++)
                    {
