                        // previous row gets additional coverage from s
                        int prevCovNew = prevCov | s; // cells in prev row covered from below by s
                        if (prevCovNew != fullMask) continue; // prev row must be fully covered

                        // current row coverage = expand[s] | prevDom
                        int curCov = expand[s] | prevDom;
                        int newVal = val + popcount(s);

                        if (ndp[s, curCov] > newVal)
