            for (int prevCov = 0; prevCov < states; prevCov++)
            {
                if (prevCov == fullMask && dp[prevDom, prevCov] < ans)
                    ans = dp[prevDom, prevCov];
            }
        }

        Console.WriteLine(R * C - ans);
    }

    static int popcount(int x)
    {
        int c = 0;
        while (x > 0) { c += x & 1; x >>= 1; }
        return c;
    }
}
