using System;
using System.Collections.Generic;

class Program {
    static void Main() {
        var parts = Console.ReadLine().Split();
        int n = int.Parse(parts[0]), m = int.Parse(parts[1]);
        if (n < m) { int t = n; n = m; m = t; }
        // n >= m, n rows, m cols
        // minimum dominating set via bitmask DP on columns
        int full = (1 << n) - 1;
        // For a column mask sel, compute coverage within column (sel | vertical neighbors of sel)
        // dp[cov_prev][sel_prev] = min selected cells
        int INF = 1000000;
        int[,] dp = new int[1<<n, 1<<n];
        for (int i = 0; i < (1<<n); i++) for (int j = 0; j < (1<<n); j++) dp[i,j] = INF;
        dp[0, 0] = 0;

        Func<int,int> vertCover = (sel) => {
            int cov = sel;
            cov |= (sel << 1) & full;
            cov |= (sel >> 1);
            return cov;
        };

        for (int col = 0; col < m; col++) {
            int[,] ndp = new int[1<<n, 1<<n];
            for (int i = 0; i < (1<<n); i++) for (int j = 0; j < (1<<n); j++) ndp[i,j] = INF;
            for (int covPrev = 0; covPrev <= full; covPrev++)
            for (int selPrev = 0; selPrev <= full; selPrev++) {
                if (dp[covPrev, selPrev] == INF) continue;
                for (int sel = 0; sel <= full; sel++) {
                    int vc = vertCover(sel);
                    int coveredPrev = covPrev | vc | selPrev; // prev col coverage
                    if (col > 0 && coveredPrev != full) continue;
                    int covCur = vc | (selPrev); // current col covered by sel's left and self
                    // selPrev covers current col from left side? No - selPrev is in prev col, covers current col to its right
                    int newCov = vc | selPrev; // current col cells covered by selPrev (right coverage) and vc
                    int cost = dp[covPrev, selPrev] + System.Numerics.BitOperations.PopCount((uint)sel);
                    if (cost < ndp[newCov, sel]) ndp[newCov, sel] = cost;
                }
            }
            dp = ndp;
        }
        int minSel = INF;
        for (int cov = 0; cov <= full; cov++)
        for (int sel = 0; sel <= full; sel++) {
            if (dp[cov,sel] == INF) continue;
            if ((cov | sel | vertCover(sel)) == full) // last col fully covered
                minSel = Math.Min(minSel, dp[cov,sel]);
        }
        Console.WriteLine(n * m - minSel);
    }
}

