using System;
using System.Numerics;

class Program {
    static void Main() {
        var parts = Console.ReadLine().Split();
        int n = int.Parse(parts[0]), m = int.Parse(parts[1]);
        if (n < m) { int t = n; n = m; m = t; }
        int full = (1 << n) - 1;
        int INF = 1000000;
        int[,] dp = new int[1<<n, 1<<n];
        for (int i=0;i<1<<n;i++) for(int j=0;j<1<<n;j++) dp[i,j]=INF;
        dp[0,0]=0;
        Func<int,int> vc = sel => { int c=sel; c|=(sel<<1)&full; c|=(sel>>1); return c; };
        for (int col=0;col<m;col++) {
            int[,] nd = new int[1<<n,1<<n];
            for(int i=0;i<1<<n;i++)for(int j=0;j<1<<n;j++)nd[i,j]=INF;
            for(int cp=0;cp<=full;cp++) for(int sp=0;sp<=full;sp++) {
                if(dp[cp,sp]==INF) continue;
                for(int sel=0;sel<=full;sel++) {
                    if(col>0 && (cp|vc(sp)|sp|vc(sel))<full) { // prev must be covered: by sp vert, cp (left coverage), and sel covers prev from right
                        int prevCov = cp | vc(sp) | sel;
                        if((prevCov&full)!=full) continue;
                    }
                    int newCov = sp | vc(sel);
                    int cost = dp[cp,sp] + BitOperations.PopCount((uint)sel);
                    if(cost < nd[newCov,sel]) nd[newCov,sel]=cost;
                }
            }
            dp=nd;
        }
        int minS=INF;
        for(int cp=0;cp<=full;cp++) for(int sp=0;sp<=full;sp++) {
            if(dp[cp,sp]==INF) continue;
            if((cp|vc(sp)|sp)==full) minS=Math.Min(minS,dp[cp,sp]);
        }
        Console.WriteLine(n*m-minS);
    }
}
