class Program {
    static void Main() {
        var parts = Console.ReadLine().Split();
        int R = int.Parse(parts[0]), C = int.Parse(parts[1]);
        if (C > R) { int t = R; R = C; C = t; }
        // R >= C, C <= 6 (since R*C<=40, C<=6 when R>=C)
        int full = (1 << C) - 1;
        // dp[prev_sel][prev_cov] = min total selected
        var INF = 1000000;
        var dp = new int[1<<C, 1<<C];
        for (int i = 0; i < (1<<C); i++) for (int j = 0; j < (1<<C); j++) dp[i,j] = INF;
        dp[0, 0] = 0;
        for (int r = 0; r < R; r++) {
            var ndp = new int[1<<C, 1<<C];
            for (int i = 0; i < (1<<C); i++) for (int j = 0; j < (1<<C); j++) ndp[i,j] = INF;
            for (int ps = 0; ps <= full; ps++) for (int pc = 0; pc <= full; pc++) {
                if (dp[ps,pc] == INF) continue;
                for (int cs = 0; cs <= full; cs++) {
                    int cc = pc | cs | (cs<<1) | (cs>>1) & full;
                    cc = pc | cs | ((cs<<1)&full) | (cs>>1);
                    cc |= ps; // covered by prev row selection
                    // prev row coverage: must be fully covered
                    int prev_final_cov = pc | cs; // prev row also gets covered by cur_sel
                    if (prev_final_cov != full && r > 0) continue;
                    if (r == 0 && prev_final_cov != 0) {} // first row, pc=0 always
                    int cost = dp[ps,pc] + CountBits(cs);
                    if (cost < ndp[cs, cc]) ndp[cs, cc] = cost;
                }
            }
            dp = ndp;
        }
        int ans = INF;
        for (int ps = 0; ps <= full; ps++)
            if (dp[ps, full] < ans) ans = dp[ps, full];
        Console.WriteLine(R*C - ans);
    }
    static int CountBits(int x) { int c=0; while(x>0){c+=x&1;x>>=1;} return c; }
}
