using System;

class Solution
{
    static long psi(long n)
    {
        string s = n.ToString();
        long result = 0;
        foreach (char c in s)
        {
            result = result * 10 + (9 - (c - '0'));
        }
        return result;
    }

    static long weight(long n)
    {
        return n * psi(n);
    }

    static void Main()
    {
        var ss = Console.ReadLine().Split(' ');
        long l = long.Parse(ss[0]);
        long r = long.Parse(ss[1]);

        // Candidates: l, r, and for each digit count, the "midpoint" candidates
        long max = 0;

        // Check all candidates
        // For each prefix length, try numbers ending in 0s and 9s
        var candidates = new System.Collections.Generic.List<long>();
        candidates.Add(l);
        candidates.Add(r);

        // For numbers with d digits, peak is near 4999...9 or 5000...0
        for (int d = 1; d <= 10; d++)
        {
            long lo = 1;
            for (int i = 0; i < d - 1; i++) lo *= 10;
            long hi = lo * 10 - 1;

            // Try 4999...9 and 5000...0 patterns for this digit count
            long mid1 = 5 * lo - 1; // 4999...9
            long mid2 = 5 * lo;     // 5000...0

            candidates.Add(Math.Max(l, Math.Min(r, mid1)));
            candidates.Add(Math.Max(l, Math.Min(r, mid2)));
            candidates.Add(Math.Max(l, Math.Min(r, lo)));
            candidates.Add(Math.Max(l, Math.Min(r, hi)));
        }

        foreach (long c in candidates)
        {
            if (c >= l && c <= r)
            {
                long w = weight(c);
                if (w > max) max = w;
            }
        }

        Console.WriteLine(max);
    }
}

