#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll mod = 1e9+7;

int main(){
    int n, x, pos;
    cin >> n >> x >> pos;

    int l = 0, r = n;
    int less_count = 0, greater_count = 0;

    while(l < r){
        int mid = (l+r)/2;
        if(mid == pos) break;
        else if(mid < pos){
            less_count++;
            l = mid + 1;
        } else {
            greater_count++;
            r = mid;
        }
    }

    // Check if we can satisfy constraints
    if(less_count > x-1 || greater_count > n-x){
        cout << 0;
        return 0;
    }

    // Compute answer
    // P(x-1, less_count) * P(n-x, greater_count) * (n-1-less_count-greater_count)!
    ll ans = 1;

    // P(x-1, less_count)
    for(int i = 0; i < less_count; i++){
        ans = ans * ((x-1-i) % mod) % mod;
    }

    // P(n-x, greater_count)
    for(int i = 0; i < greater_count; i++){
        ans = ans * ((n-x-i) % mod) % mod;
    }

    // (n-1-less_count-greater_count)!
    int rem = n - 1 - less_count - greater_count;
    for(int i = 1; i <= rem; i++){
        ans = ans * i % mod;
    }

    cout << ans;
    return 0;
}

