#include <bits/stdc++.h>
#define ll long long
using namespace std;

ll ext_gcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1;
    ll g = ext_gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

ll bigmod(ll a, ll b, ll mod) {
    ll res = 1; a %= mod;
    while (b > 0) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b /= 2;
    }
    return res;
}

int main() {
    ll a, b, p, rng;
    cin >> a >> b >> p >> rng;
    ll ans = 0;
    ll period = p - 1;
    // For each r in [0, p-2], n ≡ r (mod p-1), a^n ≡ a^r (mod p)
    // Need n * a^r ≡ b (mod p) => n ≡ b * inv(a^r) (mod p)
    // CRT: n ≡ r (mod p-1), n ≡ nmod_p (mod p)
    for (ll r = 0; r < period; r++) {
        ll ar = bigmod(a, r, p);
        ll ar_inv = bigmod(ar, p - 2, p);
        ll nmod_p = b * ar_inv % p;
        // CRT: find n ≡ r (mod p-1), n ≡ nmod_p (mod p)
        // n = r + k*(p-1), need r + k*(p-1) ≡ nmod_p (mod p)
        // k*(p-1) ≡ nmod_p - r (mod p)
        ll inv_pm1 = bigmod(period % p, p - 2, p);
        ll diff = ((nmod_p - r) % p + p) % p;
        ll k = diff * inv_pm1 % p;
        ll n0 = r + k * period;
        ll mod = p * period;
        if (n0 == 0) n0 = mod;
        if (n0 >= 1 && n0 <= rng)
            ans += (rng - n0) / mod + 1;
    }
    cout << ans << endl;
    return 0;
}

