typedef long long ll;
ll pw(ll a,ll b,ll m){ll r=1;a%=m;for(;b;b>>=1){if(b&1)r=r*a%m;a=a*a%m;}return r;}
ll inv(ll a){return pw(a,MOD-2,MOD);}
int main(){
    int n,k;ll l;
    scanf("%d%d%lld",&n,&k,&l);
    int N=n+5;
    vector<ll>fac(2*N+5),ifac(2*N+5);
    fac[0]=1;for(int i=1;i<2*N+5;i++)fac[i]=fac[i-1]*i%MOD;
    ifac[2*N+4]=inv(fac[2*N+4]);for(int i=2*N+3;i>=0;i--)ifac[i]=ifac[i+1]*(i+1)%MOD;
    auto C=[&](int a,int b)->ll{if(b<0||b>a)return 0;return fac[a]%MOD*ifac[b]%MOD*ifac[a-b]%MOD;};
    // precompute inner sum S[m] = sum_{j=k}^{m} C(m,j)*(-1)^(m-j)
    // ans = l * sum_{m=k}^{n} C(n,m)*2^m*(m!)^2/(2m+1)! * S[m]
    ll ans=0;
    for(int m=k;m<=n;m++){
