        for(int j=k;j<=m;j++){
            ll term=C(m,j);
            if((m-j)%2==1)term=MOD-term;
            Sm=(Sm+term)%MOD;
        }
        ll coeff=C(n,m)%MOD*pw(2,m,MOD)%MOD*fac[m]%MOD*fac[m]%MOD*ifac[2*m+1]%MOD;
        ans=(ans+coeff%MOD*Sm)%MOD;
    }
    ans=ans%(MOD)*((l%MOD+MOD)%MOD)%MOD;
    printf("%lld\n",ans);
}

