const int MOD = 998244353;
typedef long long ll;
ll pw(ll a, ll b, ll m=MOD){ll r=1;a%=m;for(;b;b>>=1){if(b&1)r=r*a%m;a=a*a%m;}return r;}
ll inv(ll a){return pw(a,MOD-2);}

int main(){
    int n,k; ll l;
    scanf("%d%d%lld",&n,&k,&l);
    // dp[left][used]: used in {0,1}
    int N=n+2;
    vector<vector<ll>> cur(N,vector<ll>(2,0)), nxt(N,vector<ll>(2,0));
    cur[0][0]=1;
    for(int len=1;len<=2*n+1;len++){
        for(auto&v:nxt)v[0]=v[1]=0;
        for(int left=0;left<=n;left++){
            for(int used=0;used<=1;used++){
                ll val=cur[left][used];
                if(!val)continue;
                // add opening endpoint
                if(left+1<=n) nxt[left+1][used]=(nxt[left+1][used]+val)%MOD;
                // add closing endpoint
                if(left>0) nxt[left-1][used]=(nxt[left-1][used]+val%MOD*left)%MOD;
