const int MOD = 998244353;
typedef long long ll;
ll pw(ll a,ll b,ll m){ll r=1;a%=m;for(;b;b>>=1){if(b&1)r=r*a%m;a=a*a%m;}return r;}
int main(){
    int n,k; ll l; cin>>n>>k>>l;
    int N=4*n+10;
    vector<ll>fac(N+1),inv_fac(N+1);
    fac[0]=1;for(int i=1;i<=N;i++)fac[i]=fac[i-1]*i%MOD;
    inv_fac[N]=pw(fac[N],MOD-2,MOD);
    for(int i=N-1;i>=0;i--)inv_fac[i]=inv_fac[i+1]*(i+1)%MOD;
    auto C=[&](int a,int b)->ll{if(b<0||b>a)return 0;return fac[a]%MOD*inv_fac[b]%MOD*inv_fac[a-b]%MOD;};
