        int b=n-j;
        for(int m=0;m<=b;m++){
            ll term=C(b,m)*J(j+m)%MOD;
            if(m%2==0) Iab=(Iab+term)%MOD;
            else Iab=(Iab-term+MOD)%MOD;
        }
        ans=(ans+C(n,j)*Iab)%MOD;
    }
    ans=ans%(MOD)*( l%MOD)%MOD;
    printf("%lld\n",ans);
}
