#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll pw(ll a, ll b, ll M) {
    ll x = 1;
    for (; b > 0; b >>= 1) {
        if (b & 1) x = x * a % M;
        a = a * a % M;
    }
    return x;
}

ll ext_gcd(ll a, ll b, ll &x, ll &y) {
    if (!b) { x=1; y=0; return a; }
    ll r = ext_gcd(b, a%b, y, x);
    y -= a/b * x;
    return r;
}

int main(){
    ios_base::sync_with_stdio(0); cin.tie(0);
    ll a, b, p, L;
    cin >> a >> b >> p >> L;

    // n * a^n ≡ b (mod p)
    // period of a^n mod p divides p-1
    // n mod p determines n's contribution
    // combined period is lcm(p, p-1) = p*(p-1)

    ll period = p * (p - 1);
    ll ans = 0;

    // For each r in [0, p-2], a^n ≡ a^r (mod p) when n ≡ r (mod p-1)
    // Then n ≡ b * inv(a^r) (mod p)
    // So n ≡ r (mod p-1) and n ≡ c (mod p) where c = b*inv(a^r) mod p
    // Use CRT to find n mod period

    ll inv_ar = pw(a, p-1-0, p); // will compute per r
    ll ar = 1;
    for (ll r = 0; r < p-1; r++) {
        // a^n ≡ ar (mod p), ar = a^r mod p
        ll c = b % p * pw(ar, p-2, p) % p; // n ≡ c (mod p)
        if (c == 0) c = p; // n must be positive, n≡0 mod p means n=p,2p,...

        // CRT: n ≡ r (mod p-1), n ≡ c (mod p)
        // n = r + (p-1)*t, need r + (p-1)*t ≡ c (mod p)
        // (p-1)*t ≡ c-r (mod p)
        // (-1)*t ≡ c-r (mod p)
        // t ≡ r-c (mod p)
        ll rhs = ((r - c) % p + p) % p;
        ll t0 = rhs; // t ≡ t0 (mod p)

        ll n0 = r + (p-1)*t0; // base solution, n0 ≡ n0 (mod period)
        if (n0 == 0) n0 = period;

        // n = n0 + period*k, find how many in [1, L]
        if (n0 < 1 || n0 > L) {
            if (n0 > L) { ar = ar * a % p; continue; }
        }
        ll count = (L - n0) / period + 1;
        ans += count;

        ar = ar * a % p;
    }

    cout << ans << endl;
    return 0;
}

