    if (n < 2) return false;
    for (long long i = 2; i * i <= n; i++)
        if (n % i == 0) return false;
    return true;
}

// Count ways to write N as product of sigma(p^k) for distinct primes p > lastp
long long DP(long long N, long long lastp) {
    if (N == 1) return 1;
    auto key = make_pair(N, lastp);
    auto it = dp.find(key);
    if (it != dp.end()) return it->second;

    long long sol = 0;

    // Try N-1 as a prime (sigma(prime) = prime+1 = N), prime must be > lastp
    if (N - 1 > lastp && isPrime(N - 1)) {
        sol++;
    }

    // Try prime p > lastp, power k >= 2: sigma(p^k) = 1+p+...+p^k divides N
    for (long long p = lastp + 1; p * p <= N; p++) {
        if (!isPrime(p)) continue;
        long long sigma = 1 + p; // k=1 handled above as prime case... wait k=1: sigma(p^1) = 1+p
