    for(int i = 0; i < m; i++){
        int u, v;
        cin >> u >> v;
        u--; v--;
        g[u].push_back(v);
        grev[v].push_back(u);
    }

    int k;
    cin >> k;
    vector<int> path(k);
    for(int i = 0; i < k; i++){
        cin >> path[i];
        path[i]--;
    }

    int t = path[k-1];

    // BFS from t on reversed graph
    vector<long long> dist(n, -1);
    queue<int> q;
    dist[t] = 0;
    q.push(t);
    while(!q.empty()){
        int v = q.front(); q.pop();
        for(int u : grev[v]){
            if(dist[u] == -1){
                dist[u] = dist[v] + 1;
                q.push(u);
            }
        }
    }

    long long ansMin = 0, ansMax = 0;

    for(int i = 0; i < k-1; i++){
        int cur = path[i];
        int nxt = path[i+1];

        if(dist[nxt] != dist[cur] - 1){
            // Not on shortest path, must rebuild
            ansMin++;
            ansMax++;
        } else {
            // On shortest path, no rebuild needed for min
            // For max: check if navigator could have picked different neighbor
            bool otherExists = false;
            for(int nb : g[cur]){
                if(nb != nxt && dist[nb] == dist[cur] - 1){
                    otherExists = true;
                    break;
                }
            }
            if(otherExists) ansMax++;
        }
    }

    cout << ansMin << " " << ansMax << endl;

    return 0;
}

