template<typename T>
class Segment {
public:
  T sum;
  T range_min;
  T left_min;
  T right_min;
  T mn;
  Segment(): sum(0),
	     range_min(std::numeric_limits<T>::max()),
	     left_min(std::numeric_limits<T>::max()),
	     right_min(std::numeric_limits<T>::max()),
	     mn(std::numeric_limits<T>::max()){}
  Segment(T x) : sum(x), range_min(x), left_min(x), right_min(x), mn(x){}
