template <typename T>
Segment<T> Segment<T>::operator=(const T& x) {
  sum = x;
  range_min = x;
  left_min = x;
  right_min = x;
  mn = x;
  return *this;
}

template <typename T>
void Segment<T>::Swap(Segment<T>& a) {
  swap(sum, a.sum);
  swap(range_min, a.range_min);
  swap(left_min, a.left_min);
  swap(right_min, a.right_min);
  swap(mn, a.mn);
}

