#include <iostream>
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;

int countNines(ll x) {
    if (x <= 0) return 0;
    int c = 0;
    while (x > 0 && x % 10 == 9) { c++; x /= 10; }
    return c;
}

int main(){
    ios_base::sync_with_stdio(false); cin.tie(NULL);
    ll p, d;
    cin >> p >> d;

    ll ans = p; // at minimum, answer is p (reduction of 0)
    int bestNines = countNines(p);

    // Try each possible number of trailing nines from 1 to 19
    ll pw = 10;
    for (int k = 1; k <= 19; k++) {
        // largest number with k trailing nines <= p
        ll suffix = pw - 1; // 10^k - 1
        ll candidate;
        if (p % pw == suffix) {
            candidate = p;
        } else {
            // (p / pw) * pw + suffix, but if > p, subtract pw
            ll base = (p / pw) * pw;
            candidate = base + suffix;
            if (candidate > p) candidate -= pw;
        }

        if (candidate >= 0 && p - candidate <= d) {
            int cn = countNines(candidate);
            if (cn > bestNines || (cn == bestNines && candidate > ans)) {
                bestNines = cn;
                ans = candidate;
            }
        }

        // Overflow check
        if (pw > (ll)1e18 / 10) break;
        pw *= 10;
    }

    cout << ans << endl;
    return 0;
}

