Let me write the complete solution:

```cpp
#include <iostream>
#include <string>
#include <map>
using namespace std;
string str;
int n;
map<pair<int,int>, string> dp;
const string BAD(201, 'z');

string better(const string& a, const string& b) {
    if (a == BAD) return b;
    if (b == BAD) return a;
    if (a.size() != b.size()) return a.size() < b.size() ? a : b;
    return min(a, b);
}

string solve(int i, int at_used) {
    if (i == n) return at_used == 1 ? "" : BAD;
    auto key = make_pair(i, at_used);
    if (dp.count(key)) return dp[key];
    string res = BAD;
    // take char as-is
    string rest = solve(i+1, at_used);
    if (rest != BAD) res = better(res, string(1, str[i]) + rest);
    // try "dot" -> "."
    if (i+3 <= n && str.substr(i,3) == "dot" && i > 0 && i+3 < n) {
        rest = solve(i+3, at_used);
        if (rest != BAD) res = better(res, "." + rest);
    }
    // try "at" -> "@"
    if (i+2 <= n && str.substr(i,2) == "at" && at_used == 0 && i > 0 && i+2 < n) {
        rest = solve(i+2, 1);
        if (rest != BAD) res = better(res, "@" + rest);
    }
    return dp[key] = res;
}

int main() {
    cin >> str;
    n = str.size();
    cout << solve(0, 0) << endl;
}
```

