int res[N][N];
void mul(int a[][N], int b[][N]) {
    for(int i = 0; i < N; i++)
        for(int j = 0; j < N; j++) {
            res[i][j] = 0;
            for(int k = 0; k < N; k++) {
                res[i][j] = (1LL * a[i][k] * b[k][j] + res[i][j]) % mod;
