    while(p) {
        if(p & 1)
            mul(res, temp);
        mul(temp, temp);
        p >>= 1;
    }
    for(int i = 0; i < N; i++)
        for(int j = 0; j < N; j++)
            temp[i][j] = res[i][j];
}
