            ans = countNoFixed(n, n, -1);
        }

        System.out.println(ans % MOD);
    }

    static long countNoFixed(int m, int n, int excluded) {
        // sequences of length m from {1..n}\{excluded} (if excluded>0) where no v has f(v)=v
        // inclusion-exclusion over subsets
        List<Integer> vals = new ArrayList<>();
        for (int v = 1; v <= n; v++) if (v != excluded && v <= m) vals.add(v);
        int sz = vals.size();
        long result = 0;
