            }
            if (!ok) continue;
            int free = m - fixed;
            int freeVals = n - 1 - sign; // n values minus excluded minus sign fixed ones
            // sequences of 'free' from 'freeVals' values
            ways = C[m][fixed]; // multinomial simplified... actually need freeVals^free
            // ways = C(m, positions for fixed) * arrangements * freeVals^free
            // Actually: multinomial * freeVals^free
            long mult = 1;
            int rem = m;
            for (int i = 0; i < sz; i++) {
