        for (int i = 0; i < 30; i++) {
            c[i][0] = 1;
            for (int j = 1; j <= i; j++)
                c[i][j] = (c[i-1][j-1] + c[i-1][j]) % MOD;
        }
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int h = n - k;
        if (h < 1 || h > n) { System.out.println(0); return; }
        // inclusion-exclusion over subsets of {1..n} containing h
        long ans = 0;
        // iterate over subsets of {1..n}\{h}
        List<Integer> others = new ArrayList<>();
        for (int v = 1; v <= n; v++) if (v != h) others.add(v);
        int m = others.size();
        for (int mask = 0; mask < (1 << m); mask++) {
            List<Integer> S = new ArrayList<>();
            S.add(h);
            for (int i = 0; i < m; i++) if ((mask >> i & 1) == 1) S.add(others.get(i));
            int sz = S.size(), total = 0;
            for (int v : S) total += v;
            if (total > n) continue;
            int rem = n - total, choices = n - sz;
            long ways = 1;
            int left = n;
            for (int v : S) { ways = ways % MOD * c[left][v] % MOD; left -= v; }
            long pw = 1;
            for (int i = 0; i < rem; i++) pw = pw * choices % MOD;
            ways = ways * pw % MOD;
            if ((sz - 1) % 2 == 0) ans = (ans + ways) % MOD;
            else ans = (ans - ways + MOD) % MOD;
        }
        System.out.println(ans);
    }
}

