import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        long m = 1000000007;
        long x = s.nextLong();
        long n = s.nextLong();

        ArrayList<Long> list = new ArrayList<>();

        for (long i = 2; i * i <= x; i++) {
            if (x % i == 0) {
                list.add(i);
                while (x % i == 0) x /= i;
            }
        }
        if (x > 1) list.add(x);

        long ans = 1;

        for (int i = 0; i < list.size(); i++) {
            long p = list.get(i);
            long count = 0;
            long pk = p;
            while (pk <= n) {
                count += n / pk;
                if (pk > n / p) break;
                pk *= p;
            }
            ans = (ans * power(p, count, m)) % m;
        }

        System.out.println(ans);
    }

    public static long power(long a, long b, long m) {
        long res = 1;
        a %= m;
        while (b > 0) {
            if (b % 2 != 0) res = res * a % m;
            b /= 2;
            a = a * a % m;
        }
        return res;
    }
}
