    long minCostMaxFlow(int s, int t) {
        for (int i = 0; i < n; i++) {
            d[i] = INF;
        }
        d[s] = 0;
        boolean ok = false;
        while (!ok) {
            ok = true;
            for (int j = 0; j < m; j++)
                if (fl[j] < cp[j]) {
                    int x = src[j];
                    int y = dst[j];
                    if (d[x] < INF) {
                        if (d[y] > d[x] + ct[j]) {
                            d[y] = d[x] + ct[j];
                            ok = false;
                        }
                    }
                }
        }
        long res = 0;
        maxFlow = 0;
        while (true) {
            dijkstra(s);
            if (bestDist[t] == INF) break;
            {
                int i = t;
                int f = Integer.MAX_VALUE;
                while (i != s) {
                    int e = prev[i];
                    f = Math.min(f, cp[e] - fl[e]);
                    i = src[e];
                }
                if (f < 0) throw new RuntimeException();
                maxFlow += f;
                i = t;
                while (i != s) {
                    int e = prev[i];
                    fl[e] += f;
                    fl[e ^ 1] -= f;
                    if (fl[e] > cp[e]) throw new RuntimeException();
                    res += ct[e] * f;
                    i = src[e];
                }
            }
            for (int i = 0; i < n; i++) {
                d[i] += bestDist[i];
            }
        }
        return res;
    }

    private static final long INF = Long.MAX_VALUE / 2;

    int n, m;
    int[] head;
    int[] nx;
    int[] src;
    int[] dst;
    int[] cp;
    long[] ct;
    int[] fl;
    int last;

