    long[] bestDist;
    int[] prev;
    int[] heap;
    int[] heapRev;
    int heapSize;
    long maxFlow;

    private void dijkstra(int start) {
        Arrays.fill(bestDist, INF);
        heapSize = n;
        for (int i = 0; i < n; i++) {
            heap[i] = i;
            heapRev[i] = i;
        }
        bestDist[start] = 0;
        siftUp(heapRev[start]);
        for (int i = 0; i < n; i++) {
            int x = removeMin();
            if (bestDist[x] == INF) {
