                    if (dd < 0) {
                        dd = 0;
                    }
                    long ll = bestDist[x] + dd;
                    if (bestDist[y] > ll) {
                        prev[y] = j;
                        bestDist[y] = ll;
                        siftUp(heapRev[y]);
                    }
                }
                j = nx[j];
            }
        }
    }

    private void siftUp(int i) {
        while (i > 0 && bestDist[heap[(i - 1) / 2]] > bestDist[heap[i]]) {
            swap(i, (i - 1) / 2);
            i = (i - 1) / 2;
        }
    }

    private int removeMin() {
        int res = heap[0];
        swap(0, heapSize - 1);
        heapSize--;
        int i = 0;
        while (2 * i + 1 < heapSize) {
            int j = i;
            if (bestDist[heap[2 * i + 1]] < bestDist[heap[j]]) {
                j = 2 * i + 1;
            }
            if (2 * i + 2 < heapSize && bestDist[heap[2 * i + 2]] < bestDist[heap[j]]) {
                j = 2 * i + 2;
            }
            if (i == j) break;
            swap(i, j);
            i = j;
        }
        return res;
    }

    private void swap(int i, int j) {
        int t = heap[i];
        heap[i] = heap[j];
        heap[j] = t;
        heapRev[heap[i]] = i;
        heapRev[heap[j]] = j;
    }
}
