public class Main {
    static final long MOD = 1_000_000_007L;

    static long pow(long a, long b, long m) {
        long res = 1; a %= m;
        while (b > 0) { if ((b&1)==1) res=res*a%m; a=a*a%m; b>>=1; }
        return res;
    }

    static long inv(long a) { return pow(a, MOD-2, MOD); }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        // Factorize n
        List<long[]> factors = new ArrayList<>();
        long tmp = n;
        for (long p = 2; p * p <= tmp; p++) {
            if (tmp % p == 0) {
                int exp = 0;
                while (tmp % p == 0) { exp++; tmp /= p; }
                factors.add(new long[]{p, exp});
            }
        }
        if (tmp > 1) factors.add(new long[]{tmp, 1});

        long ans = 1;

        for (long[] pe : factors) {
            long p = pe[0];
            int a = (int)pe[1];
            // dp[e] = prob of exponent e, start at exponent a
            long[] dp = new long[a+1];
            dp[a] = 1;
            long[] invs = new long[a+2];
            for (int i = 1; i <= a+1; i++) invs[i] = inv(i);

            for (int step = 0; step < k; step++) {
                long[] ndp = new long[a+1];
                for (int e = 0; e <= a; e++) {
                    if (dp[e] == 0) continue;
                    long contrib = dp[e] * invs[e+1] % MOD;
                    for (int j = 0; j <= e; j++) {
                        ndp[j] = (ndp[j] + contrib) % MOD;
                    }
                }
                dp = ndp;
            }

            // Compute E[p^e]
            long expected = 0;
            long ppow = 1;
            for (int e = 0; e <= a; e++) {
                expected = (expected + dp[e] * ppow) % MOD;
                ppow = ppow * (p % MOD) % MOD;
            }
            ans = ans * expected % MOD;
        }

        System.out.println(ans);
    }
}
```

This works because exponents evolve independently. Each prime has exponent at most 50 (since 2^50 > 10^15), so the inner DP is O(a^2 * k) per prime, which is at most O(50^2 * 10^4) = very fast.

