```java
import java.util.*;
public class C {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a=sc.nextLong(),b=sc.nextLong(),c=sc.nextLong(),l=sc.nextLong();
        long total=0;
        for(long s=0;s<=l;s++) total+=(s+1)*(s+2)/2;
        long invalid=0;
        long[] ts={b+c-a,a+c-b,a+b-c};
        for(int i=0;i<3;i++){
            long ti=ts[i];
            for(long s=0;s<=l;s++){
                long lo=(s+ti+1)/2; // ceiling of (s+ti)/2, but need 2*da >= s+ti, so da >= ceil((s+ti)/2)
                // Actually if s+ti is even: lo=(s+ti)/2, if odd: lo=(s+ti+1)/2
                // But we want 2*da >= s+ti (not strict since degenerate means >=)
                if((s+ti)%2==0) lo=(s+ti)/2; else lo=(s+ti+1)/2;
                if(lo<0) lo=0;
                if(lo>s) continue;
                long cnt=s-lo+1;
                invalid+=cnt*(cnt+1)/2;
            }
        }
        System.out.println(total-invalid);
    }
}
