import java.util.Scanner;

public class NewYearandOldPropertyB {
    public static void main(String[] args) {
        Scanner key = new Scanner(System.in);
        long start = key.nextLong();
        long stop = key.nextLong();

        long count = 0;

        // n = number of bits (from 2 to 63)
        for (int n = 2; n <= 63; n++) {
            // All n bits are 1: (2^n - 1)
            // But for n=63, 2^63 would overflow, handle carefully
            long allOnes;
            if (n == 63) {
                allOnes = Long.MAX_VALUE; // 2^63 - 1
            } else {
                allOnes = (1L << n) - 1;
            }

            // Place the zero at position k (0 to n-2), not at leading bit position n-1
            for (int k = 0; k <= n - 2; k++) {
                long num = allOnes ^ (1L << k);
                if (num >= start && num <= stop) {
                    count++;
                }
            }
        }

        System.out.println(count);
    }
}

