			arr[i] = arr[randomPos];
			arr[randomPos] = tmp;
		}
	}

	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader in = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		solve(in, out);
		out.close();
		System.exit(0);
	}

	private static void solve(InputReader in, PrintWriter out) {

		int n = in.nextInt();
		long k = in.nextLong();
		long[] fib = new long[51];
		fib[0] = 0;
		fib[1] = 1;
		fib[2] = 2;
		for (int i = 3; i <= 50; i++) {
			fib[i] = fib[i - 1] + fib[i - 2];
		}

		int pos = 1;
		int i = n;
		while (pos <= n) {
			if (pos == n && k == 1) {
				out.print(pos);
				break;
			}

			if (k <= fib[i - 1]) {
				out.print(pos + " ");
				pos++;
				i -= 1;
			} else {
				k -= fib[i - 1];
				out.print((pos + 1) + " " + pos);
				pos += 2;
				i -= 2;
			}
		}

	}

