import java.util.PriorityQueue;

public class Main {

    /**
     * @param args
     * @throws IOException 
     */
    public static class Product{
        public int a;
        public int b;
        public int c;
        Product(int a,int b,int c){
            this.a=a;
            this.b=b;
            this.c=c;
        }
    }
    public static class Profit{
        public int dif;
        public int c;
        Profit(int d,int c){
            this.dif=d;
            this.c=c;
        }
    }
    public static void main(String[] args) throws IOException {
        // TODO Auto-generated method stub
        BufferedReader in=new BufferedReader(new InputStreamReader(System.in));
        //Scanner in=new Scanner(System.in);
        PrintWriter out=new PrintWriter(System.out);
        String[] cur=in.readLine().split(" ");
        int n=Integer.parseInt(cur[0]);
        int m=Integer.parseInt(cur[1]);
        int k=Integer.parseInt(cur[2]);
        Vector<Vector<Product>> vect=new Vector<Vector<Product>>();
        Vector<String> names=new Vector<String>();
        for(int i=0; i<n; i++){
            names.add(in.readLine());
            vect.add(new Vector<Product>());
            for(int j=0; j<m; j++){
                String[] product=in.readLine().split(" ");
                vect.get(i).add(new Product(Integer.parseInt(product[0]),Integer.parseInt(product[1]),Integer.parseInt(product[2])));
            }
        }
        long maxProfit=0;
        for(int i=0; i<n; i++){
            for(int j=i+1; j<n; j++){
                Vector<Product> f=vect.get(i);
                Vector<Product> s=vect.get(j);
                PriorityQueue<Profit> ch=new PriorityQueue<Profit>(m,new Comparator<Profit>(){
                    public int compare(Profit a,Profit b){
                        if(a.dif>b.dif) return -1;
                        else if(a.dif<b.dif) return 1;
                        return 0;
                    }
                });
                for(int z=0; z<m; z++){
                    ch.add(new Profit(s.get(z).b-f.get(z).a,f.get(z).c));

                }
                int curK=k;
                int curProfit=0;
                while(curK>0 && !ch.isEmpty()){
                    Profit curProf=ch.poll();
                    int step=Math.min(curK,curProf.c);
                    if(curProf.dif>0) curProfit+=step*curProf.dif;
                    else break;
                    curK-=curProf.c;
                }
                if(curProfit>maxProfit) maxProfit=curProfit;
            }
        }
        out.println(maxProfit);
        out.close();
    }

