    inv_fact[12000]=modpow(fact[12000],MOD-2,MOD);
    for(int i=11999;i>=0;i--) inv_fact[i]=inv_fact[i+1]*(i+1)%MOD;

    long denom = C(s-r+p-1,p-1);
    if(denom==0){System.out.println(0);return;}

    long numer = 0;
    for(int m=r;m<=s;m++){
      for(int k=1;k<=p;k++){
        long rem = s - (long)m*k;
        if(rem<0) break;
        // distribute rem among p-k players each in [0,m-1]
        long ways = countWays(p-k,(int)rem,m);
        long contrib = C(p-1,k-1) % MOD * ways % MOD * modpow(k,MOD-2,MOD) % MOD;
        numer = (numer+contrib)%MOD;
      }
    }

    long ans = numer % MOD * modpow(denom,MOD-2,MOD) % MOD;
    System.out.println(ans);
  }

  static long countWays(int n, int total, int maxVal){
    // ways to put total into n bins, each in [0, maxVal-1]
    long res=0;
    for(int j=0;j<=n;j++){
      long rem2=total-(long)j*maxVal;
      if(rem2<0) break;
      long c=C((int)rem2+n-1,n-1);
      if(j%2==0) res=(res+C(n,j)*c)%MOD;
      else res=(res-C(n,j)*c%MOD+MOD)%MOD;
    }
    return res;
  }

  static long C(int a,int b){
    if(a<0||b<0||b>a) return 0;
    return fact[a]*inv_fact[b]%MOD*inv_fact[a-b]%MOD;
  }

  static long modpow(long base,long exp,long mod){
    long r=1; base%=mod;
    while(exp>0){if((exp&1)==1)r=r*base%mod;base=base*base%mod;exp>>=1;}
    return r;
  }
