        long Q = C(s - r + p - 1, p - 1);
        if (Q == 0) { System.out.println(1); return; }

        long num = 0;
        // Fix player 1's score = m
        for (int m = r; m <= s; m++) {
            int rem = s - m; // remaining for p-1 players
            // j others also score m
            for (int j = 0; j <= p - 1; j++) {
                if ((long)j * m > rem) break;
                int left = rem - j * m;
                int cnt = p - 1 - j; // must score in [0, m-1]
                long ways = countWays(cnt, left, m);
                long contrib = C(p - 1, j) % MOD * ways % MOD * inv(j + 1) % MOD;
                num = (num + contrib) % MOD;
            }
        }

        long ans = num % MOD * inv((int)(Q % MOD)) % MOD;
        System.out.println(ans);
    }

    // Number of ways cnt non-negative integers, each < m, sum to S
    static long countWays(int cnt, int S, int m) {
        if (cnt == 0) return S == 0 ? 1 : 0;
        if (m == 0) return S == 0 ? 1 : 0;
        long res = 0;
        int sign = 1;
        for (int k = 0; k <= cnt && (long)k * m <= S; k++) {
            long term = C(cnt, k) * C(S - k * m + cnt - 1, cnt - 1) % MOD;
            res = (res + sign * term + MOD) % MOD;
            sign = -sign;
        }
        return res;
    }

    static long C(int a, int b) {
        if (b < 0 || a < 0 || a < b) return 0;
        if (a > 12000) return 0;
        return fact[a] * inv((int)(fact[b] * fact[a-b] % MOD)) % MOD;
    }

    static long inv(int x) {
        return pow(x, MOD - 2);
    }

    static long pow(long base, long e) {
        long res = 1; base %= MOD;
        while (e > 0) { if ((e & 1) == 1) res = res * base % MOD; base = base * base % MOD; e >>= 1; }
