<solution>
import java.util.*;
import java.io.*;

public class D_Round_51 {
    static int[] divs = new int[48];
    static int[] divIdx = new int[2521];
    static int NDIV;
    // dp[tight][rem][lcmIdx][started]
    static long[][][][] memo;
    static int[] digs;
    static int LEN;

    static int gcd(int a, int b){ return b==0?a:gcd(b,a%b); }
    static int lcm(int a,int b){ return a/gcd(a,b)*b; }

    static void initDivs(){
        NDIV=0;
        for(int i=1;i<=2520;i++){
            if(2520%i==0){
                divIdx[i]=NDIV;
                divs[NDIV++]=i;
            }
        }
    }

    // count beautiful numbers from 1..n
    static long solve(long n){
        if(n<=0) return 0;
        // extract digits
        String s = Long.toString(n);
        LEN = s.length();
        digs = new int[LEN];
        for(int i=0;i<LEN;i++) digs[i]=s.charAt(i)-'0';
        // memo[pos][tight][rem][lcmIdx][started] - too many dims
        // use iterative DP
        // state: tight(0/1), rem(0..2519), lcmIdx(0..NDIV-1), started(0/1)
        // dp[tight][rem][lcmIdx][started]
        long[][][][] cur = new long[2][2520][NDIV][2];
        long[][][][] nxt = new long[2][2520][NDIV][2];
        // init: before any digit placed
        // started=0, rem=0, lcm=1(idx of 1), tight=1
        cur[1][0][divIdx[1]][0] = 1;

        for(int pos=0;pos<LEN;pos++){
            // clear nxt
            for(long[][][] a: nxt) for(long[][] b:a) for(long[] c:b) Arrays.fill(c,0);
            int limit_dig = digs[pos];
            for(int tight=0;tight<2;tight++){
                int maxD = tight==1 ? limit_dig : 9;
                for(int rem=0;rem<2520;rem++){
                    for(int li=0;li<NDIV;li++){
                        for(int started=0;started<2;started++){
                            long val = cur[tight][rem][li][started];
                            if(val==0) continue;
                            for(int d=0;d<=maxD;d++){
                                int ntight = (tight==1 && d==maxD)?1:0;
                                if(started==0 && d==0){
                                    // still not started
                                    nxt[ntight][0][divIdx[1]][0] += val;
                                } else {
                                    // place digit d
                                    int curLcm = divs[li];
                                    int nLcm = (started==0)? (d==0?1:d) : (d==0?curLcm:lcm(curLcm,d));
                                    // d==0 doesn't affect lcm (non-zero digits only)
                                    if(d!=0) nLcm = lcm(curLcm, d);
                                    else nLcm = curLcm;
                                    if(nLcm>2520){ /* impossible since lcm of 1-9 divides 2520 */ }
                                    int nrem = (int)((rem*10L+d)%2520);
                                    int nli = divIdx[nLcm];
                                    nxt[ntight][nrem][nli][1] += val;
                                }
                            }
