    static int[] digs;
    static int nd;

    static long solve(int pos, int tight, int rem, int lcmIdx) {
        if (pos == nd) {
            if (lcmIdx == 0) return 0; // no digits placed (number = 0, not valid)
            return rem == 0 ? 1 : 0;
        }
        if (memo[pos][tight][rem][lcmIdx] >= 0) return memo[pos][tight][rem][lcmIdx];
        int limit = tight == 1 ? digs[pos] : 9;
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            int newTight = (tight == 1 && d == limit) ? 1 : 0;
            if (d == 0 && lcmIdx == 0) {
                res += solve(pos + 1, newTight, 0, 0);
            } else {
                int newLcm;
                if (lcmIdx == 0) {
                    newLcm = (d == 0) ? 1 : d;
                } else {
                    int curLcm = divisors[lcmIdx];
                    newLcm = (d == 0) ? curLcm : lcm(curLcm, d);
                }
                int newRem = (rem * 10 + d) % LCM;
                int newLcmIdx = divIdx[newLcm];
                res += solve(pos + 1, newTight, newRem, newLcmIdx);
            }
        }
        return memo[pos][tight][rem][lcmIdx] = res;
    }

    static int lcm(int a, int b) {
        return a / gcd(a, b) * b;
    }
    static int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }

    static long count(long n) {
