        digs = new int[nd];
        for (int i = 0; i < nd; i++) digs[i] = s.charAt(i) - '0';
        memo = new long[nd][2][LCM][numDivs];
        for (long[][][] a : memo) for (long[][] b : a) for (long[] c : b) Arrays.fill(c, -1);
        return solve(0, 1, 0, 0);
    }

