public class d
{
   public static long mod = 1000000007;
   public static long[] invs = new long[60];
   public static void main(String[] Args)
   {
      for (int i = 1; i < 60; i++)
      {
         invs[i] = modInv(i, mod);
      }
      Scanner sc = new Scanner(System.in);
      long x = sc.nextLong();
      int iter = sc.nextInt();
      ArrayList<Long> derp = doit(x);
      long ans = 1;
      for (int i = 0; i < derp.size(); i+=2){
         ans *= get(derp.get(i), derp.get(i + 1), iter);
         ans %= mod;
      }
