   }

   public static ArrayList<Long> doit(long x)
   {
      ArrayList<Long> ret = new ArrayList<Long>();
      for (long i = 2; i * i <= x; i++)
      {
         long p = 0;
         while (x % i == 0)
         {
            p++;
            x /= i;
         }
         if (p != 0){
            ret.add(i);
            ret.add(p);
         }
      }
      if (x != 1){
         ret.add(x);
         ret.add(1l);
      }
      return ret;
   }

   public static long get(long p, long pow, int iter)
   {
      pow++;
      int n = (int)pow;
      long[] vs = new long[n];
      vs[0] = 1;
      for (int i = 1; i < n; i++)
         vs[i] = vs[i - 1] % mod * (p % mod) % mod;

      long[][] mat = new long[n][n];
      for (int j = 0; j < n; j++)
         for (int k = 0; k <= j; k++)
            mat[j][k] = invs[j + 1];

      long[][] result = matExpo(mat, iter, mod);

      long ans = 0;
      for (int i = 0; i < n; i++)
      {
         ans += (vs[i] % mod) * result[n - 1][i];
         ans %= mod;
      }
      return ans;
   }

   public static long[][] matExpo(long[][] mat, long pow, long mod)
   {
      int n = mat.length;
      long[][] result = new long[n][n];
      for (int i = 0; i < n; i++) result[i][i] = 1 % mod;

      long[][] base = new long[n][n];
      for (int i = 0; i < n; i++)
         for (int j = 0; j < n; j++)
            base[i][j] = mat[i][j] % mod;

      while (pow > 0) {
         if (pow % 2 == 1) {
            result = mult(result, base, mod);
         }
         base = mult(base, base, mod);
         pow /= 2;
      }
      return result;
   }

   public static long[][] mult(long[][] a, long[][] b, long mod)
   {
      int n = a.length;
      long[][] ret = new long[n][n];
      for (int i = 0; i < n; i++)
         for (int k = 0; k < n; k++) {
            if (a[i][k] == 0) continue;
            for (int j = 0; j < n; j++){
               ret[i][j] += a[i][k] * b[k][j];
               ret[i][j] %= mod;
            }
         }
      return ret;
   }

   public static long modInv(long x, long mod)
   {
      return modExpo(x, mod - 2, mod);
   }

   public static long modExpo(long base, long exp, long mod)
   {
      long result = 1 % mod;
      base %= mod;
      while (exp > 0) {
         if (exp % 2 == 1) {
            result = result * base % mod;
         }
         base = base * base % mod;
         exp /= 2;
      }
      return result;
