        // Start with first digit (non-zero)
        if (a != 0) queue.add(a);
        if (b != a) queue.add(b);

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (cur > n) continue;
            lucky.add(cur);
            // Extend with digit a
            long next1 = (long) cur * 10 + a;
            long next2 = (long) cur * 10 + b;
            if (next1 <= n) queue.add((int) next1);
            if (next2 <= n && b != a) queue.add((int) next2);
        }
    }
}
