            long mid = (lo + hi) / 2;
            if (count(mid) >= n) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }

    static long count(long x) {
        long odd = (x + 1) / 2 - 1; // odd numbers >= 3
        long mult4 = x / 4 > 1 ? x / 4 - 1 : 0; // multiples of 4 >= 8
        return odd + mult4;
    }
}

